INSERT INTO kbji_classifications (code, title, level, parent_code, description, isco_code) VALUES
-- 1 Digit: Golongan Pokok (10 Major Groups KBJI 2020)
('1', 'Manajer', 'major_group', NULL, 'Merencanakan, mengarahkan, mengoordinasikan, dan mengevaluasi kegiatan operasional instansi pemerintah dan perusahaan.', '1'),
('2', 'Profesional', 'major_group', NULL, 'Menerapkan konsep ilmiah, artistik, dan teknologi tinggi dalam penelitian, perancangan sistem, dan pemecahan masalah.', '2'),
('3', 'Teknisi dan Asisten Profesional', 'major_group', NULL, 'Melaksanakan tugas teknis terapan yang berhubungan dengan riset ilmiah dan penerapan konsep operasional praktis.', '3'),
('4', 'Tenaga Tata Usaha', 'major_group', NULL, 'Melakukan pencatatan, pengorganisasian, penyimpanan, pengolahan dokumen, dan komunikasi administrasi perkantoran.', '4'),
('5', 'Tenaga Usaha Jasa dan Tenaga Penjualan', 'major_group', NULL, 'Memberikan layanan personal, perlindungan keamanan, pramuniaga, dan penjualan komoditas di pasar ritel/grosir.', '5'),
('6', 'Pekerja Terampil Pertanian, Kehutanan, dan Perikanan', 'major_group', NULL, 'Menghasilkan komoditas hayati tanaman pangan, hortikultura, kehutanan, peternakan, dan penangkapan ikan budidaya.', '6'),
('7', 'Pekerja Pengolahan, Kerajinan, dan Rekayasa Terkait', 'major_group', NULL, 'Membangun struktur fisik, membuat produk kerajinan, mencetak logam, dan merakit material industri secara presisi.', '7'),
('8', 'Operator Mesin dan Perakit', 'major_group', NULL, 'Mengoperasikan mesin industri berdaya motor, mengemudikan alat berat/transportasi, dan merakit komponen produksi.', '8'),
('9', 'Pekerja Kasar', 'major_group', NULL, 'Menjalankan tugas-tugas rutin berbasis tenaga fisik, pembersihan area, pemilahan, dan bantuan operasional umum.', '9'),
('0', 'Anggota TNI dan Kepolisian Negara RI', 'major_group', NULL, 'Menjaga kedaulatan negara Republik Indonesia, pertahanan teritorial, keamanan publik, dan ketertiban hukum nasional.', '0'),

