('12', 'Manajer Administrasi dan Komersial', 'sub_major_group', '1', 'Merencanakan dan mengarahkan operasi administrasi, keuangan, SDM, dan logistik perusahaan.', '12'),
('22', 'Profesional Kesehatan', 'sub_major_group', '2', 'Melakukan diagnosis, pengobatan, asuhan keperawatan medis, dan pencegahan penyakit manusia.', '22'),
('24', 'Profesional Bisnis dan Administrasi', 'sub_major_group', '2', 'Menerapkan analisis pasar, akuntansi keuangan, strategi hubungan masyarakat, dan manajemen proyek bisnis.', '24'),
('25', 'Profesional Teknologi Informasi dan Komunikasi (TIK)', 'sub_major_group', '2', 'Merancang, mengembangkan, menguji, dan mengamankan arsitektur perangkat lunak, sistem AI, serta jaringan data.', '25'),
('31', 'Asisten Profesional Sains dan Rekayasa', 'sub_major_group', '3', 'Melaksanakan tugas teknis keteknikan industri, otomasi mekanikal, drafter arsitektur, dan pengendalian K3/QC.', '31'),
('33', 'Asisten Profesional Bisnis dan Administrasi', 'sub_major_group', '3', 'Melaksanakan kegiatan keagenan penjualan, perantara bisnis, tata kelola kepabeanan, dan pembukuan terapan.', '33'),
('41', 'Tenaga Tata Usaha Umum dan Kantor', 'sub_major_group', '4', 'Mengerjakan pengetikan surat, pengarsipan dokumen, pemrosesan formulir, dan operasional komputasi umum.', '41'),
('42', 'Tenaga Layanan Pelanggan dan Informasi', 'sub_major_group', '4', 'Memberikan bantuan langsung kepada nasabah/konsumen, penanganan pengaduan, dan layanan meja resepsionis.', '42'),
('43', 'Tenaga Tata Usaha Angkutan dan Penyimpanan', 'sub_major_group', '4', 'Mencatat arus keluar-masuk barang pergudangan, manifes kargo transportasi, dan inventaris persediaan.', '43'),
('51', 'Tenaga Pelayanan Pribadi', 'sub_major_group', '5', 'Menyediakan layanan pengawasan fasilitas hotel, katering makan-minum, tata graha, dan pramutamu.', '51'),
('72', 'Pekerja Logam, Mesin, dan Kerajinan Terkait', 'sub_major_group', '7', 'Membentuk logam, mengoperasikan mesin perkakas bubut/milling, dan mengelas konstruksi baja industri.', '72'),

